import{S as t,o as e,c as i,a9 as l,B as p}from"./chunks/framework.DxG24V0C.js";const o="/agentsrc/images/codex/08-hero.png",r="/agentsrc/images/codex/08-assumptions.png",h="/agentsrc/images/codex/08-chain.png",d="/agentsrc/images/codex/08-panorama.png",C=JSON.parse('{"title":"Codex vs Claude Code：设计哲学对比","description":"","frontmatter":{},"headers":[],"relativePath":"codex/08-philosophy.md","filePath":"codex/08-philosophy.md","lastUpdated":1788319991000}'),c={name:"codex/08-philosophy.md"},q=Object.assign(c,{setup(g){const s=[{question:"文章提出的 3 个核心假设差异中，哪一个最能解释 Codex 和 CC 在架构上的根本分歧？",options:["两种编程语言在性能与开发效率之间的根本性选型分歧","对 Agent 定位环境假设及任务拆分策略的差异决定 80% 架构","开源社区协作与闭源商业产品在开发模式上的天然差异","两个团队在社区贡献度和代码审查标准上存在不同传统"],correct:1,explanation:'这三个假设回答了"AI Agent 是什么"这个核心问题。CC 认为 Agent=工具调用循环、可信环境、单 Agent；Codex 认为 Agent=任务编排系统、不可信环境、多 Agent。文章核心观点是这些假设差异不是随机的，而是源于团队对 Agent 本质的不同理解。'},{question:'Codex 的"多 Agent"假设引发了怎样的连锁工程反应？',options:["在单 Agent 架构基础上增加 spawn 工具即可完成集成","多 Agent 假设引发寻址持久化状态机等连锁子系统","该假设的影响范围仅限于 V2 版本功能且 V1 不支持","多 Agent 假设仅改变通信方式对整体架构影响比较有限"],correct:1,explanation:"核心假设会引发连锁反应：假设需要多 Agent，就必须有 Agent 间通信机制，因此设计了 AgentPath 寻址；有寻址就需要持久化拓扑（AgentGraphStore）；有通信就需要状态机（7 种 AgentStatus）；有子 Agent 就需要完成通知（completion watcher）。CC 没有这个假设所以这些都不需要。"},{question:"文章认为 CC 和 Codex 哪种设计哲学更好？",options:["Codex 架构更安全因此整体上设计更优更好","CC 架构更简洁因此整体上设计更优更好","没有绝对优劣本地开发选 CC 企业部署选 Codex","两者均不够完善需在未来版本中持续改进"],correct:2,explanation:'文章核心观点是"没有正确的哲学，只有适合场景的哲学"：CC 的简单性对个人开发者是优势，Codex 的复杂性对企业部署是必要的。两个产品都成功了，说明不同哲学适应不同场景。'},{question:"文章认为未来 Agent 框架的两个必然趋势是什么？",options:["使用 Rust 和 TypeScript 混合架构统一两大技术栈优势","多 Agent 为默认配置且安全策略引擎为必备基础设施","全量上下文发送与 LLM-only 压缩成为行业新标准","WebSocket 与 HTTP 混合传输成为 Agent 通信新架构"],correct:1,explanation:"文章指出两个趋势：真多 Agent 是必然（CC 社区强烈要求，CC 团队正在重构中；Codex 已成熟）；默认安全将成为必需（随着 Agent 部署到 CI/共享环境，CC 的不沙箱策略在企业场景下是劣势）。"}];return(u,a)=>{const n=t("Quiz");return e(),i("div",null,[a[0]||(a[0]=l("",121)),p(n,{questions:s})])}}});export{C as __pageData,q as default};
